import PropTypes from "prop-types";
import React from "react";
import { Bookmark } from "./Bookmark";
import { ButtonPrimary } from "./ButtonPrimary";
import { Level } from "./Level";
import { Sertifika } from "./Sertifika";
import { Tag } from "./Tag";
import { Time } from "./Time";
import line4 from "./line-4.svg";
import "./deneme.css";

export const EItimler = ({ property1 }) => {
  return (
    <div className="e-itimler">
      <div className="frame">
        <Bookmark
          className="design-component-instance-node"
          property1="default"
        />
      </div>

      <div className="frame-2">
        <div className="frame-3">
          <div className="frame-4">
            <Tag className="design-component-instance-node" />
            <Tag className="design-component-instance-node" />
            <Tag className="design-component-instance-node" />
            <Tag className="design-component-instance-node" />
          </div>

          <div className="frame-5">
            <Level
              className="design-component-instance-node"
              property1="basic"
            />
            <Time className="design-component-instance-node" />
            <Sertifika className="design-component-instance-node" />
          </div>

          <div className="frame-6">
            <div className="text-wrapper-4">TITLE</div>

            <p className="p">
              Lorem ipsum dolor sit amet consectetur. Sagittis et viverra quam
              congue. Tortor aliquam accumsan nibh est non augue nisl vel
              dictum.
            </p>
          </div>
        </div>

        <div className="frame-7">
          <div className="frame-8">
            <div className="frame-9" />

            <div className="text-wrapper-5">Instructor</div>
          </div>

          <img className="line" alt="Line" src={line4} />

          <ButtonPrimary
            className="design-component-instance-node"
            property1="default"
            text="İncele"
          />
        </div>
      </div>
    </div>
  );
};

EItimler.propTypes = {
  property1: PropTypes.oneOf(["default"]),
};
